[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — UI & UX Design Inspiration Library</title>
  <meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: oklch(100% 0 0);
      --bg-subtle: oklch(97% 0.003 265);
      --bg-surface: oklch(95% 0.005 265);
      --border: oklch(90% 0.005 265);
      --border-light: oklch(94% 0.003 265);
      --text-primary: oklch(12% 0.01 265);
      --text-secondary: oklch(42% 0.01 265);
      --text-tertiary: oklch(62% 0.01 265);
      --accent: oklch(55% 0.22 265);
      --accent-hover: oklch(48% 0.22 265);
      --accent-soft: oklch(92% 0.08 265);
      --accent-text: oklch(55% 0.22 265);
      --radius-sm: 8px;
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.06), 0 1px 2px oklch(0% 0 0 / 0.04);
      --shadow: 0 4px 16px oklch(0% 0 0 / 0.07), 0 2px 6px oklch(0% 0 0 / 0.04);
      --shadow-lg: 0 8px 32px oklch(0% 0 0 / 0.1), 0 4px 12px oklch(0% 0 0 / 0.06);
      --font: 'Inter', system-ui, -apple-system, sans-serif;
      --transition: 220ms cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ===== ANNOUNCEMENT BAR ===== */
    .announcement-bar {
      background: var(--text-primary);
      color: var(--bg);
      text-align: center;
      padding: 10px 20px;
      font-size: 13px;
      font-weight: 500;
      letter-spacing: 0.01em;
    }
    .announcement-bar a {
      color: oklch(80% 0.12 265);
      text-decoration: none;
      margin-left: 6px;
      font-weight: 600;
    }
    .announcement-bar a:hover { text-decoration: underline; }

    /* ===== NAVIGATION ===== */
    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: oklch(100% 0 0 / 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border-light);
    }
    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 60px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .nav-logo {
      font-size: 17px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      text-decoration: none;
    }
    .nav-logo span { color: var(--accent); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 4px;
      list-style: none;
    }
    .nav-links a {
      text-decoration: none;
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 500;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      transition: var(--transition);
    }
    .nav-links a:hover { color: var(--text-primary); background: var(--bg-subtle); }
    .nav-cta {
      background: var(--text-primary);
      color: var(--bg) !important;
      border-radius: var(--radius-sm) !important;
      font-weight: 600 !important;
    }
    .nav-cta:hover { background: oklch(20% 0.01 265) !important; color: var(--bg) !important; }
    .nav-mobile-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 6px;
      color: var(--text-primary);
    }

    /* ===== HERO ===== */
    .hero {
      padding: 96px 24px 80px;
      text-align: center;
      max-width: 900px;
      margin: 0 auto;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--accent-soft);
      color: var(--accent-text);
      border: 1px solid oklch(85% 0.1 265);
      border-radius: 100px;
      padding: 5px 14px;
      font-size: 12.5px;
      font-weight: 600;
      margin-bottom: 28px;
      letter-spacing: 0.01em;
    }
    .hero-badge-dot {
      width: 6px;
      height: 6px;
      background: var(--accent);
      border-radius: 50%;
      animation: pulse 2s ease-in-out infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.6; transform: scale(0.85); }
    }
    .hero h1 {
      font-size: clamp(40px, 7vw, 72px);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.04em;
      color: var(--text-primary);
      margin-bottom: 20px;
    }
    .hero h1 em {
      font-style: normal;
      color: var(--accent);
    }
    .hero-subtitle {
      font-size: clamp(16px, 2vw, 19px);
      color: var(--text-secondary);
      margin-bottom: 40px;
      line-height: 1.6;
      max-width: 540px;
      margin-left: auto;
      margin-right: auto;
    }
    .hero-actions {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .btn-primary {
      background: var(--accent);
      color: #fff;
      padding: 13px 28px;
      border-radius: var(--radius);
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      transition: var(--transition);
      border: none;
      cursor: pointer;
    }
    .btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: var(--shadow); }
    .btn-secondary {
      background: transparent;
      color: var(--text-secondary);
      padding: 13px 24px;
      border-radius: var(--radius);
      font-size: 15px;
      font-weight: 500;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      transition: var(--transition);
      border: 1.5px solid var(--border);
    }
    .btn-secondary:hover { color: var(--text-primary); border-color: oklch(75% 0.01 265); background: var(--bg-subtle); }

    /* Hero screenshot grid preview */
    .hero-visual {
      margin-top: 56px;
      position: relative;
    }
    .hero-screen-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
      max-width: 1100px;
      margin: 0 auto;
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow-lg);
    }
    .hero-screen-card {
      aspect-ratio: 9/16;
      border-radius: var(--radius);
      overflow: hidden;
      position: relative;
    }
    .hero-screen-card .screen-mock {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      padding: 10px 8px;
      gap: 6px;
    }
    .screen-header { height: 28px; border-radius: 6px; }
    .screen-body { flex: 1; border-radius: 6px; }
    .screen-footer { height: 20px; border-radius: 6px; }

    /* ===== TRUSTED BY ===== */
    .trusted-by {
      padding: 56px 24px;
      text-align: center;
    }
    .trusted-by-label {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-tertiary);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 28px;
    }
    .trusted-logos {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 40px;
      flex-wrap: wrap;
      max-width: 900px;
      margin: 0 auto;
    }
    .trusted-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      color: var(--text-tertiary);
      font-size: 14px;
      font-weight: 700;
      letter-spacing: -0.01em;
      filter: grayscale(1);
      opacity: 0.5;
      transition: var(--transition);
    }
    .trusted-logo:hover { opacity: 0.75; filter: grayscale(0); }
    .trusted-logo svg { width: 20px; height: 20px; }

    /* ===== STATS ===== */
    .stats {
      padding: 80px 24px;
      background: var(--text-primary);
      color: var(--bg);
    }
    .stats-inner {
      max-width: 900px;
      margin: 0 auto;
      text-align: center;
    }
    .stats-label {
      font-size: 13px;
      font-weight: 600;
      color: oklch(65% 0.01 265);
      letter-spacing: 0.06em;
      text-transform: uppercase;
      margin-bottom: 48px;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
    }
    .stat-item {}
    .stat-number {
      font-size: clamp(40px, 6vw, 64px);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1;
      margin-bottom: 8px;
      color: var(--bg);
    }
    .stat-number .accent { color: oklch(70% 0.2 265); }
    .stat-desc {
      font-size: 14px;
      color: oklch(60% 0.01 265);
      font-weight: 500;
    }

    /* ===== SECTION COMMON ===== */
    .section {
      padding: 96px 24px;
    }
    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .section-tag {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      color: var(--text-primary);
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 17px;
      color: var(--text-secondary);
      max-width: 520px;
      line-height: 1.65;
    }

    /* ===== FEATURE: SEARCH ===== */
    .features-search { background: var(--bg-subtle); }
    .search-header { margin-bottom: 40px; }
    .search-widget {
      background: var(--bg);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      overflow: hidden;
      border: 1px solid var(--border-light);
    }
    .search-widget-top {
      padding: 20px 24px 0;
      border-bottom: 1px solid var(--border-light);
    }
    .search-input-row {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 20px;
    }
    .search-box {
      flex: 1;
      background: var(--bg-subtle);
      border: 1.5px solid var(--border);
      border-radius: var(--radius);
      padding: 11px 16px;
      font-size: 14px;
      font-family: var(--font);
      color: var(--text-primary);
      outline: none;
      transition: var(--transition);
    }
    .search-box:focus { border-color: var(--accent); background: var(--bg); }
    .search-box::placeholder { color: var(--text-tertiary); }
    .search-btn {
      background: var(--accent);
      color: #fff;
      border: none;
      border-radius: var(--radius);
      padding: 11px 20px;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      font-family: var(--font);
      transition: var(--transition);
      white-space: nowrap;
    }
    .search-btn:hover { background: var(--accent-hover); }

    /* Tabs */
    .search-tabs {
      display: flex;
      gap: 0;
    }
    .tab-btn {
      background: none;
      border: none;
      border-bottom: 2px solid transparent;
      padding: 12px 18px;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      font-family: var(--font);
      transition: var(--transition);
      white-space: nowrap;
    }
    .tab-btn:hover { color: var(--text-primary); }
    .tab-btn.active {
      color: var(--accent);
      border-bottom-color: var(--accent);
      font-weight: 600;
    }

    /* Filter Pills */
    .filter-pills-row {
      display: flex;
      gap: 8px;
      padding: 16px 24px;
      overflow-x: auto;
      scrollbar-width: none;
      border-bottom: 1px solid var(--border-light);
    }
    .filter-pills-row::-webkit-scrollbar { display: none; }
    .pill {
      background: var(--bg-subtle);
      border: 1.5px solid var(--border);
      border-radius: 100px;
      padding: 6px 14px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      white-space: nowrap;
      transition: var(--transition);
      font-family: var(--font);
    }
    .pill:hover { border-color: oklch(75% 0.01 265); color: var(--text-primary); }
    .pill.active {
      background: var(--text-primary);
      border-color: var(--text-primary);
      color: var(--bg);
      font-weight: 600;
    }

    /* Screenshot grid */
    .screenshot-grid {
      padding: 24px;
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 12px;
      min-height: 280px;
    }
    .screenshot-card {
      aspect-ratio: 9/16;
      border-radius: var(--radius);
      overflow: hidden;
      position: relative;
      cursor: pointer;
      transition: var(--transition);
    }
    .screenshot-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
    .screenshot-card .inner {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      padding: 8px 6px;
      gap: 5px;
    }

    /* Tab content panels */
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    /* UI Elements panel */
    .ui-elements-grid {
      padding: 24px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }
    .ui-el-card {
      background: var(--bg-subtle);
      border-radius: var(--radius);
      padding: 20px;
      border: 1px solid var(--border-light);
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .ui-el-tag {
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: var(--text-tertiary);
    }
    .ui-el-preview {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }

    /* Flows panel */
    .flows-grid {
      padding: 24px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }
    .flow-card {
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--border-light);
    }
    .flow-header {
      padding: 12px 14px;
      border-bottom: 1px solid var(--border-light);
      font-size: 12px;
      font-weight: 600;
      color: var(--text-secondary);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .flow-screens {
      display: flex;
      padding: 10px;
      gap: 6px;
    }
    .flow-screen-mini {
      flex: 1;
      aspect-ratio: 9/16;
      border-radius: 5px;
    }
    .flow-count {
      background: var(--bg-subtle);
      border-radius: 100px;
      padding: 2px 8px;
      font-size: 10px;
      font-weight: 600;
      color: var(--text-tertiary);
    }

    /* Text in screenshot panel */
    .text-panel {
      padding: 24px;
    }
    .text-search-row {
      display: flex;
      gap: 10px;
      margin-bottom: 16px;
    }
    .text-search-box {
      flex: 1;
      background: var(--bg-subtle);
      border: 1.5px solid var(--border);
      border-radius: var(--radius);
      padding: 10px 14px;
      font-size: 13.5px;
      font-family: var(--font);
      color: var(--text-primary);
      outline: none;
    }
    .text-results {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
    }
    .text-result-card {
      border-radius: var(--radius);
      overflow: hidden;
      border: 1.5px solid var(--border-light);
      aspect-ratio: 9/16;
      position: relative;
    }
    .text-result-highlight {
      position: absolute;
      bottom: 20%;
      left: 10%;
      right: 10%;
      background: oklch(88% 0.14 90 / 0.9);
      border-radius: 4px;
      padding: 4px 8px;
      font-size: 10px;
      font-weight: 600;
      color: oklch(30% 0.08 90);
    }

    /* ===== FEATURE: FLOWS ===== */
    .features-flows-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .flows-toggle-row {
      display: flex;
      background: var(--bg-surface);
      border-radius: var(--radius);
      padding: 4px;
      gap: 4px;
      width: fit-content;
      margin-bottom: 32px;
      border: 1px solid var(--border-light);
    }
    .toggle-btn {
      background: none;
      border: none;
      border-radius: var(--radius-sm);
      padding: 8px 18px;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      font-family: var(--font);
      transition: var(--transition);
    }
    .toggle-btn.active {
      background: var(--bg);
      color: var(--text-primary);
      font-weight: 600;
      box-shadow: var(--shadow-sm);
    }
    .flows-mode-content { display: none; }
    .flows-mode-content.active { display: block; }
    .flows-feature-item {
      display: flex;
      gap: 16px;
      margin-bottom: 24px;
    }
    .flows-feature-icon {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      background: var(--accent-soft);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: var(--accent);
    }
    .flows-feature-icon svg { width: 18px; height: 18px; }
    .flows-feature-title {
      font-size: 15px;
      font-weight: 600;
      margin-bottom: 4px;
    }
    .flows-feature-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }
    .flows-visual {
      background: var(--bg-subtle);
      border-radius: var(--radius-xl);
      padding: 24px;
      border: 1px solid var(--border-light);
    }
    .flows-visual-videos {
      display: flex;
      gap: 12px;
    }
    .video-card {
      flex: 1;
      aspect-ratio: 9/19;
      border-radius: var(--radius);
      overflow: hidden;
      position: relative;
      background: var(--text-primary);
    }
    .video-play-btn {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 44px;
      height: 44px;
      background: oklch(100% 0 0 / 0.15);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      backdrop-filter: blur(8px);
    }
    .video-play-btn svg { width: 18px; height: 18px; color: #fff; margin-left: 2px; }
    .flows-visual-proto {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .proto-screen {
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--border-light);
    }
    .proto-main {
      aspect-ratio: 9/16;
      position: relative;
    }
    .proto-hotspot {
      position: absolute;
      border: 2px solid var(--accent);
      border-radius: 6px;
      background: oklch(55% 0.22 265 / 0.1);
      animation: hotspot-pulse 2s ease-in-out infinite;
    }
    @keyframes hotspot-pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }
    .proto-steps {
      display: flex;
      gap: 8px;
      padding: 8px;
    }
    .proto-step-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--border);
      flex-shrink: 0;
      margin-top: 5px;
      transition: var(--transition);
    }
    .proto-step-dot.active { background: var(--accent); }
    .proto-step-label {
      font-size: 11px;
      color: var(--text-secondary);
    }

    /* ===== FEATURE: TOOLS ===== */
    .features-tools { background: var(--bg-subtle); }
    .tools-header { margin-bottom: 56px; }
    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .tool-card {
      background: var(--bg);
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid var(--border-light);
      transition: var(--transition);
    }
    .tool-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .tool-visual {
      padding: 24px 24px 0;
      background: var(--bg-subtle);
      border-bottom: 1px solid var(--border-light);
      overflow: hidden;
      height: 200px;
      display: flex;
      align-items: flex-end;
    }
    .tool-info {
      padding: 24px;
    }
    .tool-title {
      font-size: 17px;
      font-weight: 700;
      margin-bottom: 8px;
      letter-spacing: -0.02em;
    }
    .tool-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* Figma mock */
    .figma-mock {
      width: 100%;
      background: oklch(20% 0.01 265);
      border-radius: var(--radius) var(--radius) 0 0;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .figma-toolbar {
      display: flex;
      gap: 6px;
      align-items: center;
    }
    .figma-dot { width: 8px; height: 8px; border-radius: 50%; }
    .figma-canvas {
      background: oklch(30% 0.01 265);
      border-radius: var(--radius-sm);
      padding: 10px;
      display: flex;
      gap: 8px;
    }
    .figma-frame {
      background: var(--bg);
      border-radius: 4px;
      flex: 1;
      aspect-ratio: 9/14;
    }

    /* Collections mock */
    .collections-mock {
      width: 100%;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 6px;
    }
    .coll-card {
      aspect-ratio: 1;
      border-radius: var(--radius-sm);
    }

    /* Comments mock */
    .comments-mock {
      width: 100%;
      background: var(--bg);
      border-radius: var(--radius) var(--radius) 0 0;
      border: 1px solid var(--border-light);
      overflow: hidden;
    }
    .comment-item {
      display: flex;
      gap: 10px;
      padding: 10px 12px;
      border-bottom: 1px solid var(--border-light);
    }
    .comment-avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .comment-bubble {
      background: var(--bg-subtle);
      border-radius: var(--radius-sm);
      padding: 6px 10px;
      flex: 1;
    }
    .comment-name { font-size: 10px; font-weight: 600; margin-bottom: 2px; }
    .comment-text { font-size: 11px; color: var(--text-secondary); }

    /* ===== TESTIMONIALS ===== */
    .testimonials { overflow: hidden; padding: 96px 0; }
    .testimonials-header {
      text-align: center;
      padding: 0 24px;
      margin-bottom: 48px;
    }
    .marquee-wrapper {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .marquee-row {
      display: flex;
      gap: 16px;
      overflow: hidden;
    }
    .marquee-track {
      display: flex;
      gap: 16px;
      animation: marquee-left 35s linear infinite;
      will-change: transform;
    }
    .marquee-row:nth-child(2) .marquee-track {
      animation: marquee-right 40s linear infinite;
    }
    @keyframes marquee-left {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    @keyframes marquee-right {
      0% { transform: translateX(-50%); }
      100% { transform: translateX(0); }
    }
    .testimonial-card {
      background: var(--bg);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-lg);
      padding: 24px;
      min-width: 340px;
      max-width: 340px;
      flex-shrink: 0;
      box-shadow: var(--shadow-sm);
    }
    .testimonial-quote {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 16px;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .testimonial-avatar {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--bg-surface);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 700;
      color: var(--text-secondary);
    }
    .testimonial-name { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
    .testimonial-handle { font-size: 12px; color: var(--text-tertiary); }
    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 12px;
    }
    .star { color: oklch(72% 0.15 60); font-size: 13px; }

    /* ===== CTA SECTION ===== */
    .cta-section {
      padding: 96px 24px 0;
      text-align: center;
      overflow: hidden;
    }
    .cta-inner {
      max-width: 640px;
      margin: 0 auto;
      margin-bottom: 64px;
    }
    .cta-title {
      font-size: clamp(32px, 5vw, 52px);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.1;
      margin-bottom: 16px;
    }
    .cta-subtitle {
      font-size: 16px;
      color: var(--text-secondary);
      margin-bottom: 36px;
      line-height: 1.65;
    }
    .cta-actions {
      display: flex;
      gap: 12px;
      justify-content: center;
      flex-wrap: wrap;
    }

    /* App icon marquees */
    .app-marquees {
      background: var(--bg-subtle);
      border-top: 1px solid var(--border-light);
      padding: 32px 0;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .app-row {
      display: flex;
      gap: 12px;
      overflow: hidden;
    }
    .app-track {
      display: flex;
      gap: 12px;
      animation: marquee-left 25s linear infinite;
      will-change: transform;
    }
    .app-row:nth-child(2) .app-track {
      animation: marquee-right 28s linear infinite;
    }
    .app-icon {
      width: 56px;
      height: 56px;
      border-radius: 14px;
      background: var(--bg);
      border: 1px solid var(--border-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: var(--text-secondary);
      flex-shrink: 0;
      box-shadow: var(--shadow-sm);
      letter-spacing: -0.02em;
    }

    /* ===== FOOTER ===== */
    .footer {
      padding: 56px 24px 32px;
      border-top: 1px solid var(--border-light);
    }
    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      padding-bottom: 48px;
      border-bottom: 1px solid var(--border-light);
      margin-bottom: 32px;
    }
    .footer-brand {}
    .footer-logo {
      font-size: 16px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      text-decoration: none;
      display: block;
      margin-bottom: 12px;
    }
    .footer-logo span { color: var(--accent); }
    .footer-tagline {
      font-size: 13.5px;
      color: var(--text-secondary);
      line-height: 1.6;
      max-width: 240px;
    }
    .footer-col-title {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: var(--text-tertiary);
      margin-bottom: 16px;
    }
    .footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-links a {
      font-size: 13.5px;
      color: var(--text-secondary);
      text-decoration: none;
      transition: var(--transition);
    }
    .footer-links a:hover { color: var(--text-primary); }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }
    .footer-copy { font-size: 12.5px; color: var(--text-tertiary); }
    .footer-copy a { color: var(--text-tertiary); text-decoration: none; }
    .footer-copy a:hover { color: var(--text-secondary); text-decoration: underline; }
    .footer-legal {
      display: flex;
      gap: 20px;
    }
    .footer-legal a {
      font-size: 12.5px;
      color: var(--text-tertiary);
      text-decoration: none;
    }
    .footer-legal a:hover { color: var(--text-secondary); text-decoration: underline; }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .hero-screen-grid { grid-template-columns: repeat(4, 1fr); }
      .hero-screen-card:last-child { display: none; }
      .features-flows-inner { grid-template-columns: 1fr; gap: 40px; }
      .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
    }

    @media (max-width: 768px) {
      .hero { padding: 64px 20px 56px; }
      .nav-links { display: none; }
      .nav-mobile-toggle { display: block; }
      .nav-cta-mobile { display: none; }
      .hero-screen-grid { grid-template-columns: repeat(3, 1fr); }
      .hero-screen-card:nth-child(n+4) { display: none; }
      .stats-grid { grid-template-columns: repeat(3, 1fr); gap: 24px; }
      .screenshot-grid { grid-template-columns: repeat(3, 1fr); }
      .flows-grid { grid-template-columns: repeat(2, 1fr); }
      .ui-elements-grid { grid-template-columns: repeat(2, 1fr); }
      .tools-grid { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-brand { grid-column: 1 / -1; }
      .text-results { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 480px) {
      .hero h1 { font-size: 36px; }
      .stats-grid { grid-template-columns: 1fr; gap: 32px; }
      .hero-screen-grid { grid-template-columns: repeat(2, 1fr); }
      .hero-screen-card:nth-child(n+3) { display: none; }
      .screenshot-grid { grid-template-columns: repeat(2, 1fr); }
      .flows-grid { grid-template-columns: 1fr; }
      .text-results { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .testimonial-card { min-width: 280px; }
    }

    /* ===== MOBILE MENU ===== */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg);
      z-index: 200;
      padding: 20px 24px;
      flex-direction: column;
    }
    .mobile-menu.open { display: flex; }
    .mobile-menu-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 32px;
    }
    .mobile-menu-close {
      background: none;
      border: none;
      cursor: pointer;
      padding: 6px;
      color: var(--text-primary);
    }
    .mobile-menu-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .mobile-menu-links a {
      display: block;
      padding: 14px 12px;
      font-size: 17px;
      font-weight: 500;
      color: var(--text-primary);
      text-decoration: none;
      border-radius: var(--radius-sm);
    }
    .mobile-menu-links a:hover { background: var(--bg-subtle); }

    /* Decorative color helpers for mock screens */
    .c1 { background: oklch(72% 0.12 265); }
    .c2 { background: oklch(78% 0.09 210); }
    .c3 { background: oklch(82% 0.1 160); }
    .c4 { background: oklch(80% 0.12 30); }
    .c5 { background: oklch(76% 0.11 300); }
    .c6 { background: oklch(85% 0.08 80); }
    .c7 { background: oklch(70% 0.13 350); }
    .c8 { background: oklch(88% 0.06 200); }
    .cb { background: var(--border-light); }
    .cs { background: var(--bg-surface); }
    .cd { background: var(--text-primary); }
    .cw { background: var(--bg); }
    .ca { background: var(--accent); }
    .cm { background: oklch(50% 0.15 265); }
  </style>
</head>
